from ute_common_abstract_core.instance_loader import create_instance_from_class_fullname

CLASS = 'CLASS'
CONSTRUCTOR_PARAMETERS = 'CONSTRUCTOR_PARAMETERS'
# NAME_ARG_FOR_CONSTRUCTOR = 'name'


def create_mbms_app(definition, ue):
    """
    Creates mbms application object according to given name and definition

    Following keys are used from definition dictionary in creation:

    {'CLASS':'package1.module1.ClassName1', CONSTRUCTOR_PARAMETERS': {...}}

    MbmsApp class to be created and parameters to be passed into it's constructor
    Please note that 'CLASS' is provided in fully qualified name (package.module.class).

    :param name: Name for the MbmsApp, name will be forwarded to MbmsApp constructor
    :param definition: Dictionary that contains mpms app class to create and what parameters to pass into it's constructor
    :return: mbms_app
    """
    if CONSTRUCTOR_PARAMETERS in definition:
        costruct_params = dict(definition[CONSTRUCTOR_PARAMETERS])
        costruct_params['ue'] = ue
    else:
        costruct_params = dict(configuration={}, ue=ue)  # noqa: C408
    mbms_app_class_fullname = get_mbms_app_class_fullname(definition[CLASS])
    mbms_app = create_instance_from_class_fullname(class_fullname=mbms_app_class_fullname, constructor_parameters=costruct_params)
    return mbms_app


def get_mbms_app_class_fullname(mbms_app_class_name):
    """
    Ensure we have full package.module.class name for given MbmsApp
    :param mbms_app_class_name: MbmsApp type or fullname
    :return: full package.module.class name
    """
    if "." in mbms_app_class_name:
        mbms_app_class_fullname = mbms_app_class_name
    else:
        mbms_app_type = mbms_app_class_name
        mbms_app_class_fullname = convert_mbms_app_type_2_mbms_app_fullname(mbms_app_type)
    return mbms_app_class_fullname


def convert_mbms_app_type_2_mbms_app_fullname(mbms_app_type):
    """
    Encapsulate convention how to produce full package.module.class name for given MbmsApp type
    :param mbms_app_type: MbmsApp type
    :return: full package.module.class name
    """
    class_name = mbms_app_type
    module_name = class_name.replace('App', '_app').lower()
    package_name = "ute_ue.mbms_sessions.applications.{}".format(module_name.replace('_app', ''))
    mbms_app_class_name = f"{package_name}.{module_name}.{class_name}"
    return mbms_app_class_name
